package com.brasa.restaurant.controller;import com.brasa.restaurant.dto.Dtos.*;import com.brasa.restaurant.service.AuthService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/auth")public class AuthController{private final AuthService service;public AuthController(AuthService s){service=s;}@PostMapping("/login")public AuthResponse login(@Valid@RequestBody LoginRequest x){return service.login(x);}@GetMapping("/me")public UsuarioResponse me(){return service.me();}}
